const msg = $input.first().json.body.message;

const callId = msg.call?.id || "";
const phone = msg.call?.customer?.number || "";
const transcript = msg.transcript || msg.artifact?.transcript || "";
const duration = msg.durationSeconds || 0;
const startedAt = msg.startedAt || new Date().toISOString();
const endedReason = msg.endedReason || "";

return [{
  json: {
    callId,
    phone,
    transcript,
    duration,
    startedAt,
    endedReason
  }
}];

const raw = $input.first().json.content.parts[0].text;

// Strip markdown backticks if present
const cleaned = raw.replace(/```json|```/g, '').trim();

let extracted;
try {
  extracted = JSON.parse(cleaned);
} catch(e) {
  extracted = {
    callerName: "", intent: "Enquiry", customerType: "New",
    items: "", orderTotal: 0, deliveryFee: 0, grandTotal: 0,
    deliveryType: "N/A", address: "", paymentMethod: "N/A",
    partySize: 0, reservationDate: "", reservationTime: "",
    specialRequest: "", escalationIssue: "", summary: "",
    frequentOrdersUpdate: ""
  };
}

const prev = $('Extract Data').first().json;

return [{
  json: {
    callId: prev.callId,
    phone: prev.phone,
    transcript: prev.transcript,
    duration: prev.duration,
    startedAt: prev.startedAt,
    endedReason: prev.endedReason,
    ...extracted
  }
}];

const callData = $('Parse Gemini Output').first().json;
const customerRow = $input.first().json;

// Check if customer exists in sheet
const isReturning = customerRow.phone === callData.phone;

const customerProfile = {
  isNewCustomer: !isReturning,
  customerId: customerRow.customerId || "",
  customerName: callData.callerName || customerRow.name || "Unknown",
  phone: callData.phone,
  knownAddress: customerRow.address || "",
  totalOrders: customerRow.totalOrders || 0,
  frequentOrders: customerRow.frequentOrders || ""
};

return [{
  json: {
    ...callData,
    customer: customerProfile
  }
}];

